function about(){return `<section class="wrap page-intro">${tag('02 / The person behind the work')}<div class="split"><div class="prose"><h1>A little<br>about me.</h1><p class="lead"><strong>Hi, I'm Emma!</strong></p><p>I'm a creative-minded marketer with a love for brand strategy, storytelling, and bringing ideas to life.</p><p>I'm currently pursuing my M.S. in Marketing at Clemson University, where I also serve as a Marketing Graduate Assistant for Clemson Experiential Learning. Through my experience in higher education marketing, project coordination, brand research, and guest experiences at Walt Disney World, I've developed a strong foundation in creative storytelling, social media strategy, and bringing ideas from concept to execution.</p><p>I enjoy combining strategic thinking with creativity to develop ideas that connect with people and make brands memorable.</p><p>I'm especially interested in opportunities in brand strategy, creative advertising, and brand marketing, where I can bring fresh ideas and a consumer-focused perspective.</p><p>Outside of marketing, you'll usually find me exploring a new coffee shop, reading a good book, or planning my next adventure.</p></div><div class="photo-stack">${img('about.jpg','Emma portrait — replace with approved phone-booth photo before release')}</div></div></section>`}
